import React, { useEffect, useRef, useState } from 'react';
import styled from 'styled-components';
import { useLocation } from 'react-router-dom';
import { FaRegUser, FaUsers, FaSignOutAlt, FaTrashAlt, FaEraser, FaProjectDiagram, FaEuroSign, FaFileInvoiceDollar, FaFileAlt, FaAddressBook, FaMoon, FaSun } from 'react-icons/fa';
import { MdPersonAddAlt1 } from 'react-icons/md';
import { VerifyEmail } from './VerifyEmail';
import { LanguagePicker } from './LanguagePicker';
import { KnowMeBrand } from './styles/knowme';
import { useAppSettings } from 'hooks/useAppSettings';
import { uiText } from 'utils/uiTranslations';
import {
  ItemDescription,
  ItemIcon,
  ItemLabel,
  MenuItem,
} from './ProfileDotsMenu.styled';
import {
  ModalActionRow,
  ModalDangerButton,
  ModalGhostButton,
  ModalText,
  ModalTitle,
} from './InfoModal';

const MenuShell = styled.nav`
  width: 100%;
  min-width: 280px;
  text-align: left;
  font-family: var(--km-font);
  color: var(--km-text);
`;

// Лого живе тут: на телефоні верхній рядок віддано вмісту сторінки (пошук,
// роль і статус), і окремого рядка під лого більше немає.
const MenuHeader = styled.div`
  padding: 2px 10px 10px;
`;

const MenuSection = styled.div`
  padding: 8px 0;
  border-top: 1px solid var(--km-border);

  &:first-of-type {
    border-top: none;
    padding-top: 0;
  }
`;

const SectionLabel = styled.div`
  margin: 4px 10px 4px;
  color: var(--km-muted);
  font-size: 13px;
  font-weight: 600;
`;

const ActivePill = styled.span`
  padding: 3px 8px;
  border-radius: 999px;
  background: var(--km-accent);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
`;

const LogoutConfirmation = styled.div`
  padding: 10px 6px 6px;
  text-align: center;
`;

const LogoutIcon = styled.div`
  width: 48px;
  height: 48px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 14px;
  border-radius: 16px;
  background: var(--km-danger-bg);
  color: var(--km-danger);
  font-size: 20px;
`;

const SettingRow = styled.div`
  display: grid;
  grid-template-columns: 28px 1fr auto;
  align-items: center;
  gap: 12px;
  min-height: 52px;
  padding: 8px 10px;
  border-radius: 12px;
`;

// Доріжка з білим вибраним сегментом — та сама, що в колекціях стрічки:
// помаранчева заливка тут робила тему найгучнішим елементом меню.
const SegmentedControl = styled.div`
  display: inline-flex;
  padding: 3px;
  gap: 2px;
  border-radius: 10px;
  background: var(--km-fill);
`;

const SegmentedOption = styled.button`
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 32px;
  padding: 0 10px;
  border: none;
  border-radius: 8px;
  background: ${({ $active }) => ($active ? 'var(--km-card)' : 'transparent')};
  box-shadow: ${({ $active }) => ($active ? '0 1px 2px rgba(28, 27, 26, 0.12)' : 'none')};
  color: ${({ $active }) => ($active ? 'var(--km-text)' : 'var(--km-muted)')};
  font-family: var(--km-font);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 0.18s ease, color 0.18s ease;

  &:hover {
    color: var(--km-text);
  }

  &:focus-visible {
    outline: none;
    box-shadow: 0 0 0 3px var(--km-accent-ring);
  }
`;

// Ті самі адреси, що й вкладки `PrimaryNavigation`.
const PRIMARY_NAVIGATION_PATHS = ['/my-profile', '/matching', '/matching/create-profile'];

const normalizeAccess = access => ({
  canAccessAdd: Boolean(access?.canAccessAdd),
  canAccessMatching: Boolean(access?.canAccessMatching),
  canCreateProfiles: Boolean(access?.canCreateProfiles),
});

export const ProfileDotsMenu = ({
  navigate,
  isAdmin = false,
  access,
  isEmailVerified = true,
  showVerifyEmail = false,
  isSessionActive = true,
  onExit,
  onDeleteProfile,
  // Стирання полів анкети — друга дія з анкетою цілком, і стоїть вона в тій
  // самій секції, що й видалення, а не окремою секцією з тією ж назвою.
  onClearProfile,
  // Людина з двома ролями (донорка й агентка) може очистити дані однієї з
  // них, не чіпаючи другої. Стоїть це тут же, поруч з «Очистити анкету»:
  // незворотне живе в одному місці, а не червоною кнопкою біля «Опублікувати».
  clearRoleItems,
  onSelect,
  beforeNavigate,
  extraActions,
  extraActionsLabel,
  // Меню, відкрите з рядка спільної навігації (`PrimaryNavigation`), не
  // повторює її вкладок: «Пошук анкет», «Мої картки» й «Мій профіль» стоять
  // просто над ним, і ті самі три пункти в меню були тими самими кнопками
  // вдруге.
  omitPrimaryDestinations = false,
}) => {
  const location = useLocation();
  const { themeMode, setThemeMode, language, setLanguage } = useAppSettings();
  const [isLogoutConfirmationOpen, setIsLogoutConfirmationOpen] = useState(false);
  const [isLoggingOut, setIsLoggingOut] = useState(false);
  const cancelLogoutRef = useRef(null);
  const resolvedAccess = normalizeAccess(access);
  const canSeePrivilegedNav = isAdmin || resolvedAccess.canAccessAdd || resolvedAccess.canAccessMatching;

  const handleNavigate = path => {
    beforeNavigate?.();
    onSelect?.();
    navigate(path);
  };

  const handleAction = action => {
    onSelect?.();
    action?.();
  };

  useEffect(() => {
    if (!isLogoutConfirmationOpen) return undefined;

    cancelLogoutRef.current?.focus();
    const handleKeyDown = event => {
      if (event.key === 'Escape' && !isLoggingOut) {
        event.preventDefault();
        setIsLogoutConfirmationOpen(false);
      }
    };
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [isLogoutConfirmationOpen, isLoggingOut]);

  const handleLogout = async () => {
    setIsLoggingOut(true);
    try {
      await onExit?.();
      onSelect?.();
    } finally {
      setIsLoggingOut(false);
    }
  };

  if (isLogoutConfirmationOpen) {
    return (
      <LogoutConfirmation
        role="dialog"
        aria-modal="true"
        aria-labelledby="logout-confirmation-title"
        aria-describedby="logout-confirmation-description"
      >
        <LogoutIcon aria-hidden="true"><FaSignOutAlt /></LogoutIcon>
        <ModalTitle id="logout-confirmation-title">{uiText('Вийти з акаунта?', language)}</ModalTitle>
        <ModalText id="logout-confirmation-description">
          {uiText('Ви точно хочете завершити поточну сесію?', language)}
        </ModalText>
        <ModalActionRow>
          <ModalGhostButton
            ref={cancelLogoutRef}
            type="button"
            disabled={isLoggingOut}
            onClick={() => setIsLogoutConfirmationOpen(false)}
          >
            {uiText('Ні, залишитися', language)}
          </ModalGhostButton>
          <ModalDangerButton type="button" disabled={isLoggingOut} onClick={handleLogout}>
            {uiText(isLoggingOut ? 'Виходимо…' : 'Так, вийти', language)}
          </ModalDangerButton>
        </ModalActionRow>
      </LogoutConfirmation>
    );
  }

  const navItems = [
    { path: '/my-profile', label: uiText('Мій профіль', language), icon: <FaRegUser /> },
    ...(canSeePrivilegedNav && (isAdmin || resolvedAccess.canAccessAdd)
      ? [{ path: '/add', label: uiText('Додати анкету', language), description: uiText('Адмін-додавання профілів', language), icon: <MdPersonAddAlt1 /> }]
      : []),
    // Matching is open to every signed-in user: search is available to all, and a
    // viewer without matching access gets the limited projection of what it finds.
    { path: '/matching', label: 'Matching', description: uiText('Пошук і порівняння анкет', language), icon: <FaUsers /> },
    // Пункт названий місцем, а не дією: за ним лежать картки, які завів цей
    // читач, і лише потім — рядок, яким заводять наступну. «Додати профіль»
    // обіцяло форму, тож вертатись туди по вже заведену картку не було підстав.
    {
      path: '/matching/create-profile',
      label: uiText(isAdmin ? 'Нові профілі' : 'Створені мною', language),
      description: uiText(isAdmin ? 'Перевірка нових карток' : 'Ваші картки та створення нових', language),
      icon: <MdPersonAddAlt1 />,
    },
    ...(isAdmin ? [{ path: '/flow', label: 'Flow', icon: <FaProjectDiagram /> }] : []),
    ...(isAdmin ? [{ path: '/budget', label: 'Budget', description: 'Program budget and other expenses', icon: <FaEuroSign /> }] : []),
    ...(isAdmin ? [{ path: '/invoices', label: 'Invoices', description: 'Create and export client invoices', icon: <FaFileInvoiceDollar /> }] : []),
    ...(isAdmin ? [{ path: '/documents', label: 'Documents', description: 'Generate case documents from templates', icon: <FaFileAlt /> }] : []),
    ...(isAdmin ? [{ path: '/parties', label: 'Parties', description: 'Manage clinics, couples and other case parties', icon: <FaAddressBook /> }] : []),
  ].filter(item => !omitPrimaryDestinations || !PRIMARY_NAVIGATION_PATHS.includes(item.path));

  return (
    <MenuShell role="menu" aria-label={uiText('Навігаційне меню профілю', language)}>
      <MenuHeader>
        {/* Під лого тут стояли «Меню профілю» й рядок «Дії з анкетою та
            налаштування акаунта» — назва й переказ того, що й так видно
            пунктами нижче; прибрано на прохання власниці продукту. */}
        <KnowMeBrand tagline="" />
      </MenuHeader>

      {navItems.length > 0 && <MenuSection>
        <SectionLabel>{uiText('Навігація', language)}</SectionLabel>
        {navItems.map(item => {
          const active = location.pathname === item.path;
          return (
            <MenuItem
              key={item.path}
              type="button"
              role="menuitem"
              $active={active}
              onClick={() => handleNavigate(item.path)}
            >
              <ItemIcon>{item.icon}</ItemIcon>
              <span>
                <ItemLabel>{item.label}</ItemLabel>
                {item.description ? <ItemDescription>{item.description}</ItemDescription> : null}
              </span>
              {active ? <ActivePill>{uiText('зараз', language)}</ActivePill> : null}
            </MenuItem>
          );
        })}
      </MenuSection>}

      {extraActions?.length ? (
        <MenuSection>
          <SectionLabel>{extraActionsLabel || uiText('Ще', language)}</SectionLabel>
          {extraActions.map(item => (
            <MenuItem
              key={item.key}
              type="button"
              role="menuitem"
              $active={item.active}
              onClick={() => handleAction(item.onClick)}
            >
              <ItemIcon>{item.icon}</ItemIcon>
              <span>
                <ItemLabel>{item.label}</ItemLabel>
                {item.description ? <ItemDescription>{item.description}</ItemDescription> : null}
              </span>
              {item.active ? <ActivePill>{uiText('увімкнено', language)}</ActivePill> : null}
            </MenuItem>
          ))}
        </MenuSection>
      ) : null}

      <MenuSection>
        <SectionLabel>{uiText('Налаштування', language)}</SectionLabel>
        <SettingRow>
          <ItemIcon>{themeMode === 'dark' ? <FaMoon /> : <FaSun />}</ItemIcon>
          <span>
            <ItemLabel>{uiText('Тема', language)}</ItemLabel>
            <ItemDescription>{uiText('Оформлення застосунку', language)}</ItemDescription>
          </span>
          <SegmentedControl role="group" aria-label={uiText('Перемкнути тему', language)}>
            <SegmentedOption
              type="button"
              $active={themeMode === 'light'}
              aria-pressed={themeMode === 'light'}
              onClick={() => setThemeMode('light')}
            >
              <FaSun aria-hidden="true" /> {uiText('Світла', language)}
            </SegmentedOption>
            <SegmentedOption
              type="button"
              $active={themeMode === 'dark'}
              aria-pressed={themeMode === 'dark'}
              onClick={() => setThemeMode('dark')}
            >
              <FaMoon aria-hidden="true" /> {uiText('Темна', language)}
            </SegmentedOption>
          </SegmentedControl>
        </SettingRow>
        {/* Мов сім, і сегментований перемикач на них не ліз у рядок — вибір
            згорнутий в один рядок і розгортається сіткою (`LanguagePicker`). */}
        <LanguagePicker language={language} setLanguage={setLanguage} />
      </MenuSection>

      {/* «Акаунт» стоїть над «Анкетою»: незворотне — очистити й видалити —
          лишається останнім, окремо від звичайного виходу. */}
      {(showVerifyEmail || isSessionActive) && (
        <MenuSection>
          <SectionLabel>{uiText('Акаунт', language)}</SectionLabel>
          {showVerifyEmail && !isEmailVerified && (
            <VerifyEmail />
          )}
          {isSessionActive && onExit && (
            <MenuItem type="button" role="menuitem" onClick={() => setIsLogoutConfirmationOpen(true)}>
              <ItemIcon><FaSignOutAlt /></ItemIcon>
              <span>
                <ItemLabel>{uiText('Вийти', language)}</ItemLabel>
                <ItemDescription>{uiText('Завершити поточну сесію', language)}</ItemDescription>
              </span>
            </MenuItem>
          )}
        </MenuSection>
      )}
      {/* «Переглянути анкету» звідси прибрано: той пункт відкривав інструкцію
          «встановіть застосунок у Google Play», а мобільного застосунку більше
          немає — його власна заставка каже про це першою ж карткою стрічки.
          Пункт, який веде в нікуди, гірший за відсутній: він обіцяє дію. */}
      {(onDeleteProfile || onClearProfile || clearRoleItems?.length) && (
        <MenuSection>
          <SectionLabel>{uiText('Анкета', language)}</SectionLabel>
          {(clearRoleItems || []).map(item => (
            <MenuItem key={item.key} type="button" role="menuitem" $danger onClick={() => handleAction(item.onClick)}>
              <ItemIcon $danger><FaEraser /></ItemIcon>
              <span>
                <ItemLabel>{item.label}</ItemLabel>
                <ItemDescription>{uiText('Стерти поля цієї анкети, інші лишаються', language)}</ItemDescription>
              </span>
            </MenuItem>
          ))}
          {onClearProfile && (
            <MenuItem type="button" role="menuitem" $danger onClick={() => handleAction(onClearProfile)}>
              <ItemIcon $danger><FaEraser /></ItemIcon>
              <span>
                <ItemLabel>{uiText('Очистити анкету', language)}</ItemLabel>
                <ItemDescription>{uiText('Стерти всі поля й зняти з публікації', language)}</ItemDescription>
              </span>
            </MenuItem>
          )}
          {onDeleteProfile && (
          <MenuItem type="button" role="menuitem" $danger onClick={() => handleAction(onDeleteProfile)}>
            <ItemIcon $danger><FaTrashAlt /></ItemIcon>
            <span>
              <ItemLabel>{uiText('Видалити анкету', language)}</ItemLabel>
              <ItemDescription>{uiText('Надіслати запит на видалення профілю', language)}</ItemDescription>
            </span>
          </MenuItem>
          )}
        </MenuSection>
      )}

    </MenuShell>
  );
};
